package main

import (
	"database/sql"
	"encoding/json"
	"net/http"
	"os"
	_ "github.com/mattn/go-sqlite3"
)

func main() {
	port := os.Getenv("PORT")
	if port == "" { port = "3000" }
	db, _ := sql.Open("sqlite3", ":memory:")
	db.Exec("CREATE TABLE IF NOT EXISTS accounts (id INTEGER PRIMARY KEY, name TEXT, balance REAL)")
	db.Exec("INSERT INTO accounts (name, balance) VALUES ('Alice', 1000)")
	db.Exec("INSERT INTO accounts (name, balance) VALUES ('Bob', 500)")
	http.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]string{"status": "ok"})
	})
	http.HandleFunc("/transfer", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		if r.Method != "POST" { http.NotFound(w, r); return }
		var body struct { FromID int `json:"from_id"`; ToID int `json:"to_id"`; Amount float64 `json:"amount"` }
		json.NewDecoder(r.Body).Decode(&body)
		tx, _ := db.Begin()
		var balance float64
		tx.QueryRow("SELECT balance FROM accounts WHERE id = ?", body.FromID).Scan(&balance)
		if balance < body.Amount {
			tx.Rollback()
			w.WriteHeader(http.StatusBadRequest)
			json.NewEncoder(w).Encode(map[string]string{"error": "Insufficient funds"})
			return
		}
		tx.Exec("UPDATE accounts SET balance = balance - ? WHERE id = ?", body.Amount, body.FromID)
		tx.Exec("UPDATE accounts SET balance = balance + ? WHERE id = ?", body.Amount, body.ToID)
		tx.Commit()
		w.WriteHeader(http.StatusCreated)
		json.NewEncoder(w).Encode(map[string]string{"message": "Transfer successful"})
	})
	http.ListenAndServe(":"+port, nil)
}

