	db.Exec("INSERT INTO accounts (name, balance) VALUES ('Charlie', 250)")
	http.HandleFunc("/balance/", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		id, _ := strconv.Atoi(strings.TrimPrefix(r.URL.Path, "/balance/"))
		var acct struct { ID int; Name string; Balance float64 }
		err := db.QueryRow("SELECT id, name, balance FROM accounts WHERE id = ?", id).Scan(&acct.ID, &acct.Name, &acct.Balance)
		if err != nil { w.WriteHeader(404); json.NewEncoder(w).Encode(map[string]string{"error": "Not found"}); return }
		json.NewEncoder(w).Encode(map[string]interface{}{"id": acct.ID, "name": acct.Name, "balance": acct.Balance})
	})
	http.HandleFunc("/transfer", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		if r.Method != "POST" { http.NotFound(w, r); return }
		var body struct { FromID int `json:"from_id"`; ToID int `json:"to_id"`; Amount float64 `json:"amount"` }
		json.NewDecoder(r.Body).Decode(&body)
		tx, _ := db.Begin()
		var exists int
		tx.QueryRow("SELECT id FROM accounts WHERE id = ?", body.FromID).Scan(&exists)
		if exists == 0 { tx.Rollback(); w.WriteHeader(400); json.NewEncoder(w).Encode(map[string]string{"error": "Sender not found"}); return }
		var bal float64
		tx.QueryRow("SELECT balance FROM accounts WHERE id = ?", body.FromID).Scan(&bal)
		if bal < body.Amount { tx.Rollback(); w.WriteHeader(400); json.NewEncoder(w).Encode(map[string]string{"error": "Insufficient funds"}); return }
		tx.QueryRow("SELECT id FROM accounts WHERE id = ?", body.ToID).Scan(&exists)
		if exists == 0 { tx.Rollback(); w.WriteHeader(400); json.NewEncoder(w).Encode(map[string]string{"error": "Receiver not found"}); return }
		tx.Exec("UPDATE accounts SET balance = balance - ? WHERE id = ?", body.Amount, body.FromID)
		tx.Exec("UPDATE accounts SET balance = balance + ? WHERE id = ?", body.Amount, body.ToID)
		tx.Commit()
		w.WriteHeader(201)
		json.NewEncoder(w).Encode(map[string]string{"message": "Transfer successful"})
	})
	http.ListenAndServe(":"+port, nil)
